mapper.select:
select id, tenant_id, job_instance_id, rule_id, rule_code, rule_type, severity, status, metrics_json, failure_sample, error_message, checked_at, created_at
from (
    select id, tenant_id, job_instance_id, rule_id, rule_code, rule_type, severity, status, metrics_json, failure_sample, error_message, checked_at, created_at from batch.data_quality_check
    where tenant_id = #{tenantId} and job_instance_id = #{jobInstanceId}
    union all
    select cold.id, cold.tenant_id, cold.job_instance_id, cold.rule_id, cold.rule_code, cold.rule_type, cold.severity, cold.status, cold.metrics_json, cold.failure_sample, cold.error_message, cold.checked_at, cold.created_at
    from archive.data_quality_check_archive cold
    where cold.tenant_id = #{tenantId} and cold.job_instance_id = #{jobInstanceId}
      and not exists (select 1 from batch.data_quality_check hot where hot.id = cold.id)
) checks
order by id asc
